import React, { useState, useEffect } from 'react';
import './AIAssistant.css';

function AIAssistant({ metrics, suggestions, locations }) {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState([
    {
      type: 'assistant',
      message: "Hi! I'm your AI Carbon Assistant. I can help you understand your energy usage, suggest optimizations, and answer sustainability questions. Try asking me something!",
      timestamp: new Date()
    }
  ]);
  const [inputText, setInputText] = useState('');
  const [isTyping, setIsTyping] = useState(false);

  const quickQuestions = [
    "How can I reduce costs?",
    "What's my carbon footprint?",
    "Show me the biggest energy waster",
    "When is peak usage?",
    "Compare my locations"
  ];

  const generateResponse = (question) => {
    const q = question.toLowerCase();
    
    if (q.includes('cost') || q.includes('save') || q.includes('money')) {
      const totalSavings = suggestions.reduce((sum, s) => {
        return sum + parseFloat(s.potential_savings.replace('$', '').replace('/day', ''));
      }, 0);
      return `💰 I see ${suggestions.length} optimization opportunities that could save you $${totalSavings.toFixed(0)} per day ($${(totalSavings * 365).toFixed(0)} annually). The biggest impact would be: ${suggestions[0]?.message || 'adjusting your HVAC settings'}.`;
    }
    
    if (q.includes('carbon') || q.includes('footprint') || q.includes('emission')) {
      const totalEmissions = locations ? 
        locations.reduce((sum, loc) => sum + loc.emissions, 0) :
        parseFloat(metrics?.carbon_emissions || 0);
      return `🌍 Your current carbon footprint is ${totalEmissions.toFixed(0)} kg CO₂ per hour. That's equivalent to ${(totalEmissions / 4.6).toFixed(1)} cars running for an hour. To offset this, you'd need ${(totalEmissions / 21.8).toFixed(1)} trees planted.`;
    }
    
    if (q.includes('waste') || q.includes('biggest') || q.includes('worst')) {
      const highest = Math.max(metrics?.heating || 0, metrics?.cooling || 0, metrics?.equipment || 0);
      let category = 'equipment';
      if (highest === metrics?.heating) category = 'heating';
      if (highest === metrics?.cooling) category = 'cooling';
      return `⚡ Your ${category} systems are using the most energy at ${highest.toFixed(0)} kWh/hr. This represents ${((highest / metrics?.total_consumption) * 100).toFixed(0)}% of total consumption. Consider optimizing this area first.`;
    }
    
    if (q.includes('peak') || q.includes('when') || q.includes('time')) {
      return `📊 Based on patterns, your peak usage typically occurs between 2:00-3:00 PM when cooling and equipment demands are highest. Your current efficiency score is ${metrics?.efficiency_score?.toFixed(0) || 65}%. Consider load balancing during these hours.`;
    }
    
    if (q.includes('location') || q.includes('compare') || q.includes('building')) {
      if (locations) {
        const best = locations.reduce((best, loc) => loc.efficiency > best.efficiency ? loc : best);
        const worst = locations.reduce((worst, loc) => loc.efficiency < worst.efficiency ? loc : worst);
        return `🏢 Comparing your ${locations.length} locations: ${best.name} is your top performer at ${best.efficiency.toFixed(0)}% efficiency, while ${worst.name} needs attention at ${worst.efficiency.toFixed(0)}%. The difference represents $${((worst.cost - best.cost) * 24 * 365).toFixed(0)} in potential annual savings.`;
      }
      return `🏢 Your current building efficiency is ${metrics?.efficiency_score?.toFixed(0) || 65}%. Compared to industry average of 65%, you're performing at par. There's room for improvement to reach best-in-class 85%+ efficiency.`;
    }
    
    if (q.includes('weather') || q.includes('temperature') || q.includes('forecast')) {
      return `🌤️ Current weather conditions suggest moderate energy demand. With temperatures around 22°C, your HVAC systems are operating efficiently. I recommend pre-cooling before afternoon temperatures rise to avoid peak demand charges.`;
    }
    
    if (q.includes('alert') || q.includes('problem') || q.includes('issue')) {
      return `🔔 I'm monitoring for unusual patterns. Currently tracking energy spikes, efficiency drops, and cost anomalies. Your systems are operating within normal parameters, but I'll alert you immediately if anything changes.`;
    }
    
    // Default responses
    const responses = [
      `🤖 Based on your current usage of ${metrics?.total_consumption?.toFixed(0) || 500} kWh/hr, I recommend focusing on your highest consumption areas first.`,
      `📈 Your efficiency score of ${metrics?.efficiency_score?.toFixed(0) || 65}% shows potential for improvement. Industry leaders achieve 80%+ efficiency.`,
      `💡 I can help you analyze any aspect of your energy usage. Try asking about specific systems, costs, or environmental impact.`,
      `🎯 Your current hourly cost of $${metrics?.cost_per_hour || 85} could be reduced by 15-30% with targeted optimizations.`
    ];
    
    return responses[Math.floor(Math.random() * responses.length)];
  };

  const handleSendMessage = (text = inputText) => {
    if (!text.trim()) return;

    // Add user message
    const userMessage = {
      type: 'user',
      message: text,
      timestamp: new Date()
    };
    
    setMessages(prev => [...prev, userMessage]);
    setInputText('');
    setIsTyping(true);

    // Simulate AI thinking time
    setTimeout(() => {
      const response = generateResponse(text);
      const assistantMessage = {
        type: 'assistant',
        message: response,
        timestamp: new Date()
      };
      
      setMessages(prev => [...prev, assistantMessage]);
      setIsTyping(false);
    }, 1500);
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter') {
      handleSendMessage();
    }
  };

  return (
    <>
      <div className={`ai-assistant-toggle ${isOpen ? 'active' : ''}`} onClick={() => setIsOpen(!isOpen)}>
        <span className="assistant-icon">🤖</span>
        <span className="assistant-label">AI Assistant</span>
      </div>

      {isOpen && (
        <div className="ai-assistant-panel">
          <div className="assistant-header">
            <div className="assistant-info">
              <span className="assistant-avatar">🤖</span>
              <div>
                <h3>Carbon AI Assistant</h3>
                <span className="assistant-status">● Online</span>
              </div>
            </div>
            <button className="close-assistant" onClick={() => setIsOpen(false)}>✕</button>
          </div>

          <div className="messages-container">
            {messages.map((msg, index) => (
              <div key={index} className={`message ${msg.type}`}>
                <div className="message-content">
                  {msg.message}
                </div>
                <div className="message-time">
                  {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                </div>
              </div>
            ))}
            
            {isTyping && (
              <div className="message assistant typing">
                <div className="message-content">
                  <div className="typing-indicator">
                    <span></span>
                    <span></span>
                    <span></span>
                  </div>
                </div>
              </div>
            )}
          </div>

          <div className="quick-questions">
            <div className="quick-questions-label">Quick questions:</div>
            <div className="quick-questions-grid">
              {quickQuestions.map((question, index) => (
                <button
                  key={index}
                  className="quick-question-btn"
                  onClick={() => handleSendMessage(question)}
                >
                  {question}
                </button>
              ))}
            </div>
          </div>

          <div className="input-container">
            <input
              type="text"
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
              onKeyPress={handleKeyPress}
              placeholder="Ask me about your energy usage..."
              className="message-input"
            />
            <button 
              onClick={() => handleSendMessage()}
              className="send-button"
              disabled={!inputText.trim()}
            >
              ➤
            </button>
          </div>
        </div>
      )}
    </>
  );
}

export default AIAssistant;
